return {
    ["quota"] = 1000,
    ["lastQuotaCheckTime"] = 0,
    ["GetRequestBaseQuota"] = function(_) --[[ Name: GetRequestBaseQuota, Line 6 ]]
        return 1000
    end,
    ["GetRequestPlayerQuota"] = function(_, p1) --[[ Name: GetRequestPlayerQuota, Line 10 ]]
        return 100 * (p1 == nil and #game:GetService("Players"):GetPlayers() or p1)
    end,
    ["Get"] = function(p2) --[[ Name: Get, Line 14 ]]
        return p2.quota
    end,
    ["ProcessWriteRequest"] = function(p3) --[[ Name: ProcessWriteRequest, Line 18 ]]
        if p3.quota <= 0 then
            error("Exceeded MemoryStore quota (on write)", 2)
        end
        p3.quota = p3.quota - 1
    end,
    ["ProcessReadRequest"] = function(p4) --[[ Name: ProcessReadRequest, Line 26 ]]
        if p4.quota <= 0 then
            error("Exceeded MemoryStore quota (on read)", 2)
        end
        p4.quota = p4.quota - 1
    end,
    ["UpdateQuota"] = function(p5) --[[ Name: UpdateQuota, Line 34 ]]
        if p5.lastQuotaCheckTime < tick() + 60 then
            p5.quota = p5:GetRequestBaseQuota() + p5:GetRequestPlayerQuota()
            p5.lastQuotaCheckTime = tick()
        end
    end
}